const PptxGenJS = require('pptxgenjs');

const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches

// Color palette
const COLORS = {
  primary: '1B4F72',    // Deep blue
  secondary: '2E86C1',  // Medium blue
  accent: 'E67E22',     // Orange accent
  dark: '2C3E50',       // Dark text
  light: 'ECF0F1',      // Light background
  white: 'FFFFFF',
  gray: '7F8C8D',
};

const FONT = '微软雅黑';

// ============================================================
// Slide 1: Title Page
// ============================================================
const slide1 = pres.addSlide();
slide1.background = { color: COLORS.primary };

// Decorative top bar
slide1.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 0.15, fill: { color: COLORS.accent }
});

// Main title
slide1.addText('团队协作的力量', {
  x: 1.5, y: 1.8, w: 10.33, h: 1.5,
  fontSize: 44, fontFace: FONT, bold: true,
  color: COLORS.white, align: 'center'
});

// Subtitle
slide1.addText('打造高效协同的卓越团队', {
  x: 1.5, y: 3.3, w: 10.33, h: 0.8,
  fontSize: 24, fontFace: FONT,
  color: COLORS.light, align: 'center'
});

// Divider line
slide1.addShape(pres.ShapeType.rect, {
  x: 4.5, y: 4.3, w: 4.33, h: 0.04, fill: { color: COLORS.accent }
});

// Date / presenter info
slide1.addText('2024年度团队建设专题', {
  x: 1.5, y: 4.8, w: 10.33, h: 0.6,
  fontSize: 16, fontFace: FONT,
  color: COLORS.gray, align: 'center'
});

// Bottom decorative bar
slide1.addShape(pres.ShapeType.rect, {
  x: 0, y: 7.35, w: 13.33, h: 0.15, fill: { color: COLORS.accent }
});


// ============================================================
// Slide 2: Why Team Collaboration Matters
// ============================================================
const slide2 = pres.addSlide();
slide2.background = { color: COLORS.white };

// Header bar
slide2.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: COLORS.primary }
});
slide2.addText('为什么团队协作至关重要？', {
  x: 0.8, y: 0.15, w: 11.73, h: 0.8,
  fontSize: 28, fontFace: FONT, bold: true, color: COLORS.white
});

// Three key points with colored left borders
const points2 = [
  { title: '提升工作效率', body: '协作分工让每位成员聚焦擅长领域，减少重复劳动，整体产出提升 30% 以上。' },
  { title: '激发创新思维', body: '多元背景的团队碰撞出更多创意火花，跨职能合作是突破性创新的核心驱动力。' },
  { title: '增强组织韧性', body: '紧密协作的团队面对变化时响应更快、适应力更强，降低关键人员单点风险。' },
];

points2.forEach((p, i) => {
  const yPos = 1.6 + i * 1.8;
  // Left accent bar
  slide2.addShape(pres.ShapeType.rect, {
    x: 1.0, y: yPos, w: 0.08, h: 1.3, fill: { color: COLORS.accent }
  });
  // Title
  slide2.addText(p.title, {
    x: 1.4, y: yPos, w: 10.5, h: 0.5,
    fontSize: 22, fontFace: FONT, bold: true, color: COLORS.dark
  });
  // Body
  slide2.addText(p.body, {
    x: 1.4, y: yPos + 0.5, w: 10.5, h: 0.8,
    fontSize: 16, fontFace: FONT, color: COLORS.gray
  });
});


// ============================================================
// Slide 3: Core Elements of Effective Collaboration
// ============================================================
const slide3 = pres.addSlide();
slide3.background = { color: COLORS.white };

// Header bar
slide3.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: COLORS.primary }
});
slide3.addText('高效协作的四大核心要素', {
  x: 0.8, y: 0.15, w: 11.73, h: 0.8,
  fontSize: 28, fontFace: FONT, bold: true, color: COLORS.white
});

// Four cards in a 2x2 grid
const cards = [
  { icon: '🎯', title: '共同目标', desc: '清晰、可衡量的团队目标\n让每个人知道"为何而战"' },
  { icon: '💬', title: '开放沟通', desc: '建立心理安全感，鼓励\n坦诚反馈与信息共享' },
  { icon: '🤝', title: '信任与尊重', desc: '认可个体价值，包容差异\n在分歧中寻找共识' },
  { icon: '⚙️', title: '流程与工具', desc: '标准化协作流程，善用\n数字化工具提升协同效率' },
];

cards.forEach((c, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const xPos = 1.0 + col * 5.8;
  const yPos = 1.6 + row * 2.7;

  // Card background
  slide3.addShape(pres.ShapeType.roundRect, {
    x: xPos, y: yPos, w: 5.2, h: 2.3,
    fill: { color: COLORS.light },
    rectRadius: 0.15,
    line: { color: COLORS.secondary, width: 1.5 }
  });

